+  const lowerCaseString = inputString.toLowerCase(); // Convert the string to lowercase for case-insensitive matching
+
+  let count = 0;
+  for (const word of words) {
+    if (lowerCaseString.includes(word.toLowerCase())) {
+      count++;
+    }
+  }
+
+  return count;
+};
+
